{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "JOVRA Studio ReferenceCatalog (jovra.reference-catalog/1)",
  "description": "The trusted index of every record an EDL or StoryBrief names by id but must never carry by value: score states and point events and stats derived from the event log at one event revision, user notes, lesson notes and cues, annotations, narration consents and music rights. It is a projection that trusted code builds from the stored records (core point events and stats, Lesson, ProjectLock participants, a rights record store), never something a planner or client writes. edl.validate resolves every overlay refId, title-card textRef and narration scriptNoteId here and requires the kind and the stored provenance to match; a consentRecordId or rightsRecordId must name a stored, granted record whose scope covers the use. bundle.py cross-checks cues and lesson notes against the lessons and consents against the ProjectLock participants.",
  "type": "object",
  "required": ["schemaVersion", "projectId", "revision", "sample", "eventRevision", "references", "consents", "rights"],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {"const": "jovra.reference-catalog/1"},
    "projectId": {"$ref": "studio-common.schema.json#/$defs/id"},
    "revision": {"$ref": "studio-common.schema.json#/$defs/revision"},
    "sample": {"$ref": "studio-common.schema.json#/$defs/sample"},
    "eventRevision": {"description": "The event-log revision the score, point and stat entries were resolved at.", "$ref": "studio-common.schema.json#/$defs/revision"},
    "references": {
      "type": "array",
      "maxItems": 2000,
      "items": {
        "type": "object",
        "required": ["refId", "kind", "provenance", "eventRevision", "origin"],
        "additionalProperties": false,
        "properties": {
          "refId": {"$ref": "studio-common.schema.json#/$defs/id"},
          "kind": {"$ref": "studio-common.schema.json#/$defs/overlayKind"},
          "provenance": {"$ref": "studio-common.schema.json#/$defs/provenanceStatus"},
          "eventRevision": {"$ref": "studio-common.schema.json#/$defs/revision"},
          "origin": {
            "type": "object",
            "required": ["recordKind", "recordId"],
            "additionalProperties": false,
            "properties": {
              "recordKind": {"enum": ["point-event", "score-state", "stat", "user-note", "lesson-note", "lesson-cue", "annotation"]},
              "recordId": {"$ref": "studio-common.schema.json#/$defs/id"}
            }
          }
        }
      }
    },
    "consents": {
      "type": "array",
      "maxItems": 64,
      "items": {
        "type": "object",
        "required": ["consentRecordId", "participantId", "scope", "granted", "at"],
        "additionalProperties": false,
        "properties": {
          "consentRecordId": {"$ref": "studio-common.schema.json#/$defs/id"},
          "participantId": {"$ref": "studio-common.schema.json#/$defs/id"},
          "scope": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"enum": ["narration-voice", "generated-voice"]}},
          "granted": {"type": "boolean"},
          "at": {"$ref": "studio-common.schema.json#/$defs/dateTime"}
        }
      }
    },
    "rights": {
      "type": "array",
      "maxItems": 64,
      "items": {
        "type": "object",
        "required": ["rightsRecordId", "assetId", "holder", "scope"],
        "additionalProperties": false,
        "properties": {
          "rightsRecordId": {"$ref": "studio-common.schema.json#/$defs/id"},
          "assetId": {"$ref": "studio-common.schema.json#/$defs/id"},
          "holder": {"enum": ["user", "licensor"]},
          "scope": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"enum": ["private-film", "lesson-share", "youtube"]}}
        }
      }
    }
  }
}
"""#,
        "render-job.schema.json": #"""
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "JOVRA Studio RenderJob (jovra.render-job/1)",
  "description": "A private production job and its full transition history. The state machine lives in spec/studio/contracts/render-job-transitions.v1.json; spec/reference/studio/jobstate.py replays the history and must arrive at the stored state, resumeStage and attempt. Paid stages need a reservation; ready needs a verified delivered artifact. Stage progress is a per-stage figure, never a computed whole-job percentage.",
  "type": "object",
  "required": ["schemaVersion", "jobId", "projectId", "environment", "sample", "planId", "planRevision", "quoteId", "reservationId", "idempotencyKey", "state", "resumeStage", "attempt", "maxAttempts", "stageProgress", "deliveredArtifactIds", "history"],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {"const": "jovra.render-job/1"},
    "jobId": {"$ref": "studio-common.schema.json#/$defs/id"},
    "projectId": {"$ref": "studio-common.schema.json#/$defs/id"},
    "environment": {"$ref": "studio-common.schema.json#/$defs/environment"},
    "sample": {"$ref": "studio-common.schema.json#/$defs/sample"},
    "planId": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/id"}]},
    "planRevision": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/revision"}]},
    "quoteId": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/id"}]},
    "reservationId": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/id"}]},
    "idempotencyKey": {"description": "Canonical SHA-256 of (projectId, planRevision, outputSpec); the same request never starts a second job.", "$ref": "studio-common.schema.json#/$defs/sha256"},
    "state": {"$ref": "#/$defs/state"},
    "resumeStage": {"description": "Set only in paused, failed_retryable and budget_exceeded: one of pausableFrom / retryableFrom / budgetExceededFrom for that state (jobstate.py checks which). Never ready, deleted or any terminal state.", "oneOf": [{"type": "null"}, {"$ref": "#/$defs/resumeStage"}]},
    "attempt": {"type": "integer", "minimum": 1, "maximum": 100},
    "maxAttempts": {"type": "integer", "minimum": 1, "maximum": 100},
    "stageProgress": {
      "oneOf": [
        {"type": "null"},
        {
          "type": "object",
          "required": ["stage", "percent", "sample"],
          "additionalProperties": false,
          "properties": {
            "stage": {"$ref": "#/$defs/state"},
            "percent": {"type": "integer", "minimum": 0, "maximum": 100},
            "sample": {"type": "boolean"}
          }
        }
      ]
    },
    "deliveredArtifactIds": {"type": "array", "maxItems": 16, "uniqueItems": true, "items": {"$ref": "studio-common.schema.json#/$defs/id"}},
    "history": {
      "type": "array",
      "minItems": 1,
      "maxItems": 500,
      "items": {
        "type": "object",
        "required": ["seq", "from", "to", "at", "reason"],
        "additionalProperties": false,
        "properties": {
          "seq": {"$ref": "studio-common.schema.json#/$defs/nonNegInt"},
          "from": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/state"}]},
          "to": {"$ref": "#/$defs/state"},
          "at": {"$ref": "studio-common.schema.json#/$defs/dateTime"},
          "reason": {"type": "string", "pattern": "^[a-z][a-z0-9-]{0,47}$"}
        }
      }
    }
  },
  "$defs": {
    "resumeStage": {
      "description": "pausableFrom U retryableFrom U budgetExceededFrom of spec/studio/contracts/render-job-transitions.v1.json; validate_studio.py fails if they drift.",
      "enum": ["upload_pending", "uploading", "queued", "normalizing", "syncing", "analyzing", "planning", "preview_rendering", "awaiting_review", "final_rendering", "verifying"]
    },
    "state": {
      "enum": ["draft", "quoted", "consented", "upload_pending", "uploading", "queued", "normalizing", "syncing", "analyzing", "planning", "preview_rendering", "awaiting_review", "final_rendering", "verifying", "ready", "paused", "canceled", "failed_retryable", "failed_terminal", "quote_expired", "budget_exceeded", "deleted"]
    }
  }
}
"""#,
        "room.schema.json": #"""
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "JOVRA Room v1 messages (jovra.room/1) and host-side transcripts (jovra.room-transcript/1)",
  "description": "SD10 and ADR-0027 (as amended 2026-10-07). A jovra.room/1 message travels as one 4-byte big-endian length-prefixed UTF-8 JSON frame over TLS 1.3/TCP on the local network. Every message carries roomId, hostEpoch, the sender's deviceId, a per-sender increasing seq and the sender's own monotonic sentMonoNs (never compared with another device's clock). The receiver attributes a message by its authenticated TLS peer, never by the deviceId inside it. The QR join payload is spec/room's jovra.room.invitation-payload/1, unchanged. A transcript is one host's ordered view of a room: invitations it issued, frames it received (with the verdict the host must reach), frames it sent, approval comparisons, restarts and what its screen showed. Everything here is a proposal plus checked fixtures; nothing was exercised on a device.",
  "oneOf": [{"$ref": "#/$defs/message"}, {"$ref": "#/$defs/transcript"}],
  "$defs": {
    "id": {"$ref": "studio-common.schema.json#/$defs/id"},
    "sha256": {"$ref": "studio-common.schema.json#/$defs/sha256"},
    "nonNegInt": {"$ref": "studio-common.schema.json#/$defs/nonNegInt"},
    "posInt": {"$ref": "studio-common.schema.json#/$defs/posInt"},
    "nonce": {"description": "128-bit unpadded base64url nonce (spec/room nonce).", "type": "string", "pattern": "^[A-Za-z0-9_-]{22}$"},
    "displayCode": {"description": "Lookup label beside the QR (e.g. JVR-482). Never a secret; same pattern as jovra.camera-invite/1.", "type": "string", "pattern": "^JVR-[0-9]{3}$"},
    "sixDigits": {"type": "string", "pattern": "^[0-9]{6}$"},
    "roomHint": {"description": "The DNS-SD instance name the host advertises: an opaque random hint, never a player, project or device name (ADR-0027 section 2).", "type": "string", "pattern": "^jovra-[0-9a-z]{10}$"},
    "commandGrant": {"description": "What a participant may do. viewer is everyone's default; the camera-invite roster permission host-controls maps to capture-controller.", "enum": ["viewer", "marker", "scorer", "capture-controller"]},
    "capability": {"description": "What a slot lets a phone do with its own capture. A camera guest starts with record-local and view-own-preview only.", "enum": ["record-local", "view-own-preview", "upload-own-source"]},
    "slotRole": {"enum": ["primary", "camera"]},
    "thermal": {"description": "iOS ProcessInfo.thermalState names; Android maps PowerManager thermal status onto them.", "enum": ["nominal", "fair", "serious", "critical"]},
    "captureState": {"enum": ["Ready", "Starting", "Recording", "Paused", "Finalizing", "Stopped", "Failed"]},
    "batteryPct": {"type": "integer", "minimum": 0, "maximum": 100},
    "permission": {"enum": ["granted", "denied", "undetermined"]},
    "grants": {"type": "array", "minItems": 1, "maxItems": 4, "uniqueItems": true, "items": {"$ref": "#/$defs/commandGrant"}},
    "capabilities": {"type": "array", "maxItems": 3, "uniqueItems": true, "items": {"$ref": "#/$defs/capability"}},
    "deviceIds": {"type": "array", "maxItems": 6, "uniqueItems": true, "items": {"$ref": "#/$defs/id"}},
    "messageType": {"enum": ["hello", "join", "approvalRequest", "joinReveal", "approve", "decline", "revoke", "roleAssigned", "grantChanged", "readiness", "recordingIntent", "recordingStarted", "heartbeat", "still", "segmentEvent", "recordingStopped", "stopOne", "stopAll", "bookmark", "commandResult", "receipt"]},

    "message": {
      "type": "object",
      "required": ["schemaVersion", "roomId", "hostEpoch", "deviceId", "seq", "sentMonoNs", "type", "body"],
      "additionalProperties": false,
      "properties": {
        "schemaVersion": {"const": "jovra.room/1"},
        "roomId": {"$ref": "#/$defs/id"},
        "hostEpoch": {"description": "Rises every time a room host starts, restarts or changes. A previous epoch is never fresh authority.", "$ref": "#/$defs/posInt"},
        "deviceId": {"description": "The sender's claim. The receiver checks it against the device bound to the authenticated TLS peer.", "$ref": "#/$defs/id"},
        "seq": {"description": "Strictly increasing per sender within one hostEpoch.", "$ref": "#/$defs/posInt"},
        "sentMonoNs": {"description": "The sender's own monotonic clock that keeps counting during sleep. Only the sender may subtract its own values.", "$ref": "#/$defs/nonNegInt"},
        "type": {"$ref": "#/$defs/messageType"},
        "body": {"type": "object"}
      },
      "allOf": [
        {"if": {"properties": {"type": {"const": "hello"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/hello"}}}},
        {"if": {"properties": {"type": {"const": "join"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/join"}}}},
        {"if": {"properties": {"type": {"const": "approvalRequest"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/approvalRequest"}}}},
        {"if": {"properties": {"type": {"const": "joinReveal"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/joinReveal"}}}},
        {"if": {"properties": {"type": {"const": "approve"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/approve"}}}},
        {"if": {"properties": {"type": {"const": "decline"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/decline"}}}},
        {"if": {"properties": {"type": {"const": "revoke"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/revoke"}}}},
        {"if": {"properties": {"type": {"const": "roleAssigned"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/roleAssigned"}}}},
        {"if": {"properties": {"type": {"const": "grantChanged"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/grantChanged"}}}},
        {"if": {"properties": {"type": {"const": "readiness"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/readiness"}}}},
        {"if": {"properties": {"type": {"const": "recordingIntent"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/recordingIntent"}}}},
        {"if": {"properties": {"type": {"const": "recordingStarted"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/recordingStarted"}}}},
        {"if": {"properties": {"type": {"const": "heartbeat"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/heartbeat"}}}},
        {"if": {"properties": {"type": {"const": "still"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/still"}}}},
        {"if": {"properties": {"type": {"const": "segmentEvent"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/segmentEvent"}}}},
        {"if": {"properties": {"type": {"const": "recordingStopped"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/recordingStopped"}}}},
        {"if": {"properties": {"type": {"const": "stopOne"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/stopOne"}}}},
        {"if": {"properties": {"type": {"const": "stopAll"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/stopAll"}}}},
        {"if": {"properties": {"type": {"const": "bookmark"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/bookmark"}}}},
        {"if": {"properties": {"type": {"const": "commandResult"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/commandResult"}}}},
        {"if": {"properties": {"type": {"const": "receipt"}}}, "then": {"properties": {"body": {"$ref": "#/$defs/receipt"}}}}
      ]
    },

    "hello": {
      "type": "object",
      "required": ["role", "appVersion", "platform", "protocols", "roomHint"],
      "additionalProperties": false,
      "properties": {
        "role": {"enum": ["host", "guest"]},
        "appVersion": {"type": "string", "pattern": "^[0-9]{1,3}\\.[0-9]{1,3}(\\.[0-9]{1,3})?$"},
        "platform": {"enum": ["ios", "android"]},
        "protocols": {"type": "array", "minItems": 1, "maxItems": 1, "items": {"const": 1}},
        "roomHint": {"description": "The host's advertised hint; null from a guest.", "oneOf": [{"type": "null"}, {"$ref": "#/$defs/roomHint"}]}
      }
    },
    "join": {
      "description": "The guest's join request over the TLS channel. QR path: proves the QR secret with HMAC-SHA256(joinToken, roomId|inviteId|nonce|guestKeySha256|guestCommitment) (spec/room's proof with sessionId = roomId) and commits to its guest nonce. Typed-code path: looks the invitation up by its display code; it has no pinned host key, so its comparison code must come from the TLS channel binding (channelBinding tls-exporter) or the host refuses it. displayName is the guest's own claim, shown as unverified text and never the basis of approval.",
      "type": "object",
      "required": ["path", "inviteId", "displayCode", "guestKeySha256", "guestCommitment", "observedHostKeySha256", "proof", "channelBinding", "displayName", "deviceModel", "consent"],
      "additionalProperties": false,
      "properties": {
        "path": {"enum": ["qr", "typedCode"]},
        "inviteId": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/id"}]},
        "displayCode": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/displayCode"}]},
        "guestKeySha256": {"$ref": "#/$defs/sha256"},
        "guestCommitment": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/sha256"}]},
        "observedHostKeySha256": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/sha256"}]},
        "proof": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/sha256"}]},
        "channelBinding": {"oneOf": [{"type": "null"}, {"const": "tls-exporter"}]},
        "displayName": {"$ref": "studio-common.schema.json#/$defs/userText"},
        "deviceModel": {"type": "string", "minLength": 1, "maxLength": 80},
        "consent": {"type": "object", "required": ["shareCaptureMetadata"], "additionalProperties": false, "properties": {"shareCaptureMetadata": {"const": true}}}
      },
      "allOf": [
        {"if": {"properties": {"path": {"const": "qr"}}},
         "then": {"properties": {"inviteId": {"$ref": "#/$defs/id"}, "displayCode": {"type": "null"}, "guestCommitment": {"$ref": "#/$defs/sha256"}, "observedHostKeySha256": {"$ref": "#/$defs/sha256"}, "proof": {"$ref": "#/$defs/sha256"}, "channelBinding": {"type": "null"}}},
         "else": {"properties": {"inviteId": {"type": "null"}, "displayCode": {"$ref": "#/$defs/displayCode"}, "guestCommitment": {"type": "null"}, "observedHostKeySha256": {"type": "null"}, "proof": {"type": "null"}}}}
      ]
    },
    "approvalRequest": {
      "description": "The host accepted the join checks and now waits for the human comparison. QR path: carries the host's fresh nonce, sent only after the guest committed. Typed-code path: no nonce (the code comes from the channel binding).",
      "type": "object",
      "required": ["inviteId", "hostNonce"],
      "additionalProperties": false,
      "properties": {"inviteId": {"$ref": "#/$defs/id"}, "hostNonce": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/nonce"}]}}
    },
    "joinReveal": {
      "type": "object",
      "required": ["inviteId", "guestNonce"],
      "additionalProperties": false,
      "properties": {"inviteId": {"$ref": "#/$defs/id"}, "guestNonce": {"$ref": "#/$defs/nonce"}}
    },
    "approve": {
      "description": "Sent after the host tapped 'Codes match · Allow'. It names the guest's key, never its display name.",
      "type": "object",
      "required": ["inviteId", "deviceId", "guestKeySha256", "basis"],
      "additionalProperties": false,
      "properties": {
        "inviteId": {"$ref": "#/$defs/id"},
        "deviceId": {"$ref": "#/$defs/id"},
        "guestKeySha256": {"$ref": "#/$defs/sha256"},
        "basis": {"enum": ["comparisonCode", "channelBindingCode"]}
      }
    },
    "decline": {
      "type": "object",
      "required": ["inviteId", "reason"],
      "additionalProperties": false,
      "properties": {"inviteId": {"$ref": "#/$defs/id"}, "reason": {"enum": ["codesDidNotMatch", "hostDeclined", "attemptsExhausted"]}}
    },
    "revoke": {
      "description": "Removes a member (its connection closes and the code it used is void) or withdraws an open code.",
      "type": "object",
      "required": ["deviceId", "inviteId", "reason"],
      "additionalProperties": false,
      "properties": {
        "deviceId": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/id"}]},
        "inviteId": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/id"}]},
        "reason": {"enum": ["hostRemoved", "codeWithdrawn"]}
      }
    },
    "roleAssigned": {
      "type": "object",
      "required": ["deviceId", "slot", "slotRole", "commandGrants", "capabilities"],
      "additionalProperties": false,
      "properties": {
        "deviceId": {"$ref": "#/$defs/id"},
        "slot": {"$ref": "studio-common.schema.json#/$defs/placementSlot"},
        "slotRole": {"$ref": "#/$defs/slotRole"},
        "commandGrants": {"$ref": "#/$defs/grants"},
        "capabilities": {"$ref": "#/$defs/capabilities"}
      }
    },
    "grantChanged": {
      "type": "object",
      "required": ["deviceId", "commandGrants"],
      "additionalProperties": false,
      "properties": {"deviceId": {"$ref": "#/$defs/id"}, "commandGrants": {"$ref": "#/$defs/grants"}}
    },
    "readiness": {
      "description": "A camera's own preflight (multicam-sync section 2.7). Ready when the camera is allowed, the preset is supported, minutesLeft covers the planned length, battery is at least 20 % or charging, and thermal is nominal or fair.",
      "type": "object",
      "required": ["cameraPermission", "microphonePermission", "presetSupported", "batteryPct", "charging", "lowPowerMode", "freeBytes", "minutesLeft", "thermal"],
      "additionalProperties": false,
      "properties": {
        "cameraPermission": {"$ref": "#/$defs/permission"},
        "microphonePermission": {"$ref": "#/$defs/permission"},
        "presetSupported": {"type": "boolean"},
        "batteryPct": {"$ref": "#/$defs/batteryPct"},
        "charging": {"type": "boolean"},
        "lowPowerMode": {"type": "boolean"},
        "freeBytes": {"$ref": "#/$defs/nonNegInt"},
        "minutesLeft": {"$ref": "#/$defs/nonNegInt"},
        "thermal": {"$ref": "#/$defs/thermal"}
      }
    },
    "commandCommon": {
      "type": "object",
      "required": ["commandId", "issuer", "claimedGrant", "expiry", "target", "baseEventRevision"],
      "properties": {
        "commandId": {"description": "From a CSPRNG (at least 96 bits); unique per issuer.", "$ref": "#/$defs/id"},
        "issuer": {"type": "object", "required": ["deviceId"], "additionalProperties": false, "properties": {"deviceId": {"$ref": "#/$defs/id"}}},
        "claimedGrant": {"$ref": "#/$defs/commandGrant"},
        "expiry": {
          "description": "ttlMs is the command's lifetime; ageAtSendMs is recomputed by the issuer on every send from its own monotonic clock, and is left out of the idempotency hash.",
          "type": "object", "required": ["ttlMs", "ageAtSendMs"], "additionalProperties": false,
          "properties": {"ttlMs": {"type": "integer", "minimum": 1, "maximum": 600000}, "ageAtSendMs": {"$ref": "#/$defs/nonNegInt"}}
        },
        "target": {
          "type": "object", "required": ["scope", "deviceIds"], "additionalProperties": false,
          "properties": {"scope": {"enum": ["one", "all", "room"]}, "deviceIds": {"$ref": "#/$defs/deviceIds"}}
        },
        "baseEventRevision": {"description": "The room capture revision the issuer saw; capture commands against an older revision are Conflicted. null for a bookmark.", "oneOf": [{"type": "null"}, {"$ref": "#/$defs/nonNegInt"}]}
      }
    },
    "recordingIntent": {
      "description": "An intent to start, never proof. Only recordingStarted acknowledgements count (ADR-0017).",
      "allOf": [{"$ref": "#/$defs/commandCommon"}],
      "type": "object",
      "required": ["intentId"],
      "additionalProperties": false,
      "properties": {"commandId": true, "issuer": true, "claimedGrant": true, "expiry": true, "target": true, "baseEventRevision": true, "intentId": {"$ref": "#/$defs/id"}}
    },
    "stopOne": {
      "allOf": [{"$ref": "#/$defs/commandCommon"}],
      "type": "object",
      "additionalProperties": false,
      "properties": {"commandId": true, "issuer": true, "claimedGrant": true, "expiry": true, "target": true, "baseEventRevision": true}
    },
    "stopAll": {
      "description": "A deliberate, confirmed fan-out that names its targets; reported per device, never as a blanket success.",
      "allOf": [{"$ref": "#/$defs/commandCommon"}],
      "type": "object",
      "required": ["confirmed", "targetLabel"],
      "additionalProperties": false,
      "properties": {"commandId": true, "issuer": true, "claimedGrant": true, "expiry": true, "target": true, "baseEventRevision": true,
                     "confirmed": {"const": true}, "targetLabel": {"type": "string", "pattern": "^Stop all cameras \\([1-6]\\)$"}}
    },
    "bookmark": {
      "description": "Mark point: a match-clock hint and an optional note on the shared timeline. It never moves the capture revision.",
      "allOf": [{"$ref": "#/$defs/commandCommon"}],
      "type": "object",
      "required": ["matchClockHintMs", "note"],
      "additionalProperties": false,
      "properties": {"commandId": true, "issuer": true, "claimedGrant": true, "expiry": true, "target": true, "baseEventRevision": true,
                     "matchClockHintMs": {"$ref": "#/$defs/nonNegInt"}, "note": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/userText"}]}}
    },
    "recordingStarted": {
      "description": "A camera's acknowledgement that it is recording: the only evidence 'Recording on n of m' counts. intentId is null for a start the operator made on that phone.",
      "type": "object",
      "required": ["intentId", "segmentId", "fileZeroHostNs", "wallClockAtStart", "preset", "fps", "timescale", "orientationLock"],
      "additionalProperties": false,
      "properties": {
        "intentId": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/id"}]},
        "segmentId": {"$ref": "#/$defs/id"},
        "fileZeroHostNs": {"description": "The sender's monotonic clock at the file's first sample (multicam-sync section 3.2): a capture-time hint, never alignment evidence.", "$ref": "#/$defs/nonNegInt"},
        "wallClockAtStart": {"$ref": "studio-common.schema.json#/$defs/dateTime"},
        "preset": {"type": "object", "required": ["width", "height"], "additionalProperties": false, "properties": {"width": {"$ref": "#/$defs/posInt"}, "height": {"$ref": "#/$defs/posInt"}}},
        "fps": {"$ref": "studio-common.schema.json#/$defs/fps"},
        "timescale": {"$ref": "#/$defs/posInt"},
        "orientationLock": {"enum": ["portrait", "landscapeLeft", "landscapeRight", "none"]}
      }
    },
    "heartbeat": {
      "description": "Every 2 s. Its absence is never read as a stop: the receiver ages it.",
      "type": "object",
      "required": ["captureState", "segmentId", "savedThroughMs", "segmentIndex", "freeBytes", "batteryPct", "thermal", "droppedFrames"],
      "additionalProperties": false,
      "properties": {
        "captureState": {"$ref": "#/$defs/captureState"},
        "segmentId": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/id"}]},
        "savedThroughMs": {"$ref": "#/$defs/nonNegInt"},
        "segmentIndex": {"$ref": "#/$defs/nonNegInt"},
        "freeBytes": {"$ref": "#/$defs/nonNegInt"},
        "batteryPct": {"$ref": "#/$defs/batteryPct"},
        "thermal": {"$ref": "#/$defs/thermal"},
        "droppedFrames": {"$ref": "#/$defs/nonNegInt"}
      }
    },
    "still": {
      "description": "Preview still metadata (the image follows as its own blob): every 5 s, or every 2 s while framing, and only at thermal nominal or fair. Its age is chained from the sender's capture time; it is never 'live'.",
      "type": "object",
      "required": ["stillId", "captureMonoNs", "framing", "format", "width", "height", "bytes", "sha256"],
      "additionalProperties": false,
      "properties": {
        "stillId": {"$ref": "#/$defs/id"},
        "captureMonoNs": {"$ref": "#/$defs/nonNegInt"},
        "framing": {"type": "boolean"},
        "format": {"enum": ["jpeg", "heic"]},
        "width": {"type": "integer", "minimum": 1, "maximum": 1280},
        "height": {"type": "integer", "minimum": 1, "maximum": 1280},
        "bytes": {"type": "integer", "minimum": 1, "maximum": 262144},
        "sha256": {"$ref": "#/$defs/sha256"}
      }
    },
    "segmentEvent": {
      "type": "object",
      "required": ["segmentId", "event", "reason", "mediaMs", "nextSegmentId"],
      "additionalProperties": false,
      "properties": {
        "segmentId": {"$ref": "#/$defs/id"},
        "event": {"enum": ["interruption", "gapStart", "gapEnd", "rollover"]},
        "reason": {"oneOf": [{"type": "null"}, {"enum": ["call", "siri", "thermal", "storage", "background", "other"]}]},
        "mediaMs": {"$ref": "#/$defs/nonNegInt"},
        "nextSegmentId": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/id"}]}
      }
    },
    "recordingStopped": {
      "description": "A camera's acknowledgement that it stopped. commandId is null for a stop made on that phone.",
      "type": "object",
      "required": ["commandId", "segments"],
      "additionalProperties": false,
      "properties": {
        "commandId": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/id"}]},
        "segments": {"type": "array", "minItems": 1, "maxItems": 64, "items": {"type": "object", "required": ["segmentId", "durationMs", "bytes"], "additionalProperties": false, "properties": {"segmentId": {"$ref": "#/$defs/id"}, "durationMs": {"$ref": "#/$defs/nonNegInt"}, "bytes": {"$ref": "#/$defs/nonNegInt"}}}}
      }
    },
    "commandResult": {
      "description": "A target camera's refusal or failure of a relayed capture command.",
      "type": "object",
      "required": ["commandId", "result", "reason"],
      "additionalProperties": false,
      "properties": {
        "commandId": {"$ref": "#/$defs/id"},
        "result": {"enum": ["Failed", "Denied"]},
        "reason": {"enum": ["cameraPermissionDenied", "foregroundRequired", "finalizing", "finalizeFailed", "notRecording", "storageFull"]}
      }
    },
    "receipt": {
      "type": "object",
      "required": ["commandId", "issuerDeviceId", "status", "reason", "securityEvent", "eventRevision", "perDevice"],
      "additionalProperties": false,
      "properties": {
        "commandId": {"$ref": "#/$defs/id"},
        "issuerDeviceId": {"$ref": "#/$defs/id"},
        "status": {"enum": ["Pending", "Accepted", "Rejected", "Expired", "Conflicted"]},
        "reason": {"oneOf": [{"type": "null"}, {"type": "string", "pattern": "^[a-z][A-Za-z]{1,40}$"}]},
        "securityEvent": {"type": "boolean"},
        "eventRevision": {"$ref": "#/$defs/nonNegInt"},
        "perDevice": {
          "type": "array", "maxItems": 6,
          "items": {"type": "object", "required": ["deviceId", "result", "reason"], "additionalProperties": false,
                    "properties": {"deviceId": {"$ref": "#/$defs/id"}, "result": {"enum": ["Pending", "Accepted", "Failed", "Denied", "Unknown"]},
                                   "reason": {"oneOf": [{"type": "null"}, {"type": "string", "pattern": "^[a-z][A-Za-z]{1,40}$"}]}}}
        }
      }
    },

    "transcript": {
      "type": "object",
      "required": ["schemaVersion", "transcriptId", "sample", "screen", "title", "room", "steps"],
      "additionalProperties": false,
      "properties": {
        "schemaVersion": {"const": "jovra.room-transcript/1"},
        "transcriptId": {"$ref": "#/$defs/id"},
        "sample": {"const": true},
        "screen": {"enum": ["23-camera-lobby", "24-director-capture"]},
        "title": {"type": "string", "minLength": 1, "maxLength": 200},
        "room": {"$ref": "#/$defs/room"},
        "steps": {"type": "array", "minItems": 1, "maxItems": 400, "items": {"$ref": "#/$defs/step"}}
      }
    },
    "member": {
      "type": "object",
      "required": ["deviceId", "keySha256", "label", "slot", "slotRole", "commandGrants", "capabilities"],
      "additionalProperties": false,
      "properties": {
        "deviceId": {"$ref": "#/$defs/id"},
        "keySha256": {"$ref": "#/$defs/sha256"},
        "label": {"$ref": "studio-common.schema.json#/$defs/userText"},
        "slot": {"$ref": "studio-common.schema.json#/$defs/placementSlot"},
        "slotRole": {"$ref": "#/$defs/slotRole"},
        "commandGrants": {"$ref": "#/$defs/grants"},
        "capabilities": {"$ref": "#/$defs/capabilities"}
      }
    },
    "room": {
      "description": "The host's state when the transcript starts. members[0] is the host itself.",
      "type": "object",
      "required": ["roomId", "projectId", "hostDeviceId", "hostKeySha256", "hostEpoch", "roomHint", "maxCameras", "plannedMinutes", "eventRevision", "members"],
      "additionalProperties": false,
      "properties": {
        "roomId": {"$ref": "#/$defs/id"},
        "projectId": {"$ref": "#/$defs/id"},
        "hostDeviceId": {"$ref": "#/$defs/id"},
        "hostKeySha256": {"$ref": "#/$defs/sha256"},
        "hostEpoch": {"$ref": "#/$defs/posInt"},
        "roomHint": {"$ref": "#/$defs/roomHint"},
        "maxCameras": {"const": 6},
        "plannedMinutes": {"$ref": "#/$defs/posInt"},
        "eventRevision": {"$ref": "#/$defs/nonNegInt"},
        "members": {"type": "array", "minItems": 1, "maxItems": 6, "items": {"$ref": "#/$defs/member"}}
      }
    },
    "stepNote": {"description": "A fixture label the room vectors use to name this step.", "type": "string", "pattern": "^[a-z0-9][a-z0-9-]{0,63}$"},
    "verdict": {
      "oneOf": [
        {"type": "object", "required": ["accepted"], "additionalProperties": false, "properties": {"accepted": {"const": true}}},
        {"type": "object", "required": ["accepted", "code"], "additionalProperties": false, "properties": {"accepted": {"const": false}, "code": {"type": "string", "pattern": "^[a-z][A-Za-z]{1,40}$"}}}
      ]
    },
    "atMs": {"description": "The host's own monotonic clock, in ms (continuous across sleep).", "$ref": "#/$defs/nonNegInt"},
    "frameLength": {"description": "The 4-byte big-endian length prefix: the byte length of the message's canonical UTF-8 JSON (sorted keys, no whitespace).", "type": "integer", "minimum": 0, "maximum": 4294967295},
    "step": {
      "oneOf": [
        {
          "type": "object",
          "required": ["step", "atMs", "inviteId", "slot", "displayCode", "lifetimeS", "qr"],
          "additionalProperties": false,
          "properties": {
            "note": {"$ref": "#/$defs/stepNote"}, "step": {"const": "invite"}, "atMs": {"$ref": "#/$defs/atMs"}, "inviteId": {"$ref": "#/$defs/id"},
            "slot": {"$ref": "studio-common.schema.json#/$defs/placementSlot"}, "displayCode": {"$ref": "#/$defs/displayCode"},
            "lifetimeS": {"type": "integer", "minimum": 1, "maximum": 86400},
            "qr": {"description": "The QR text the host displays: spec/room's jovra.room.invitation-payload/1. Sample secrets only.", "type": "string", "pattern": "^[a-z-]+:[0-9]+:[A-Za-z0-9_=+/-]{1,2048}$"}
          }
        },
        {
          "type": "object",
          "required": ["step", "atMs", "peerKeySha256", "length", "transitMs", "exporter", "verdict", "message"],
          "additionalProperties": false,
          "properties": {
            "note": {"$ref": "#/$defs/stepNote"}, "step": {"const": "in"}, "atMs": {"$ref": "#/$defs/atMs"},
            "peerKeySha256": {"description": "The TLS-authenticated peer key of the channel the frame arrived on.", "$ref": "#/$defs/sha256"},
            "length": {"$ref": "#/$defs/frameLength"},
            "transitMs": {"description": "A transport-observed bound on transit (from an acknowledged exchange); null when it cannot be bounded.", "oneOf": [{"type": "null"}, {"$ref": "#/$defs/nonNegInt"}]},
            "exporter": {"description": "The host side's TLS exporter value for this channel (label EXPORTER-jovra-room-sas), present when the channel offers one. Sample value.", "oneOf": [{"type": "null"}, {"$ref": "#/$defs/sha256"}]},
            "verdict": {"$ref": "#/$defs/verdict"},
            "message": {"$ref": "#/$defs/message"}
          }
        },
        {
          "type": "object",
          "required": ["step", "atMs", "toPeerKeys", "length", "message"],
          "additionalProperties": false,
          "properties": {
            "note": {"$ref": "#/$defs/stepNote"}, "step": {"const": "out"}, "atMs": {"$ref": "#/$defs/atMs"},
            "toPeerKeys": {"type": "array", "minItems": 1, "maxItems": 6, "uniqueItems": true, "items": {"$ref": "#/$defs/sha256"}},
            "length": {"$ref": "#/$defs/frameLength"},
            "message": {"$ref": "#/$defs/message"}
          }
        },
        {
          "description": "The host phone's own action or capture report (its own UI, its own camera); it never crosses the network.",
          "type": "object",
          "required": ["step", "atMs", "message"],
          "additionalProperties": false,
          "properties": {"note": {"$ref": "#/$defs/stepNote"}, "step": {"const": "local"}, "atMs": {"$ref": "#/$defs/atMs"}, "message": {"$ref": "#/$defs/message"}}
        },
        {
          "description": "The human comparison: the six digits each screen showed and the host's tap. guestView is what the guest's side of the channel saw (a different host key or exporter means a man in the middle); null when it saw the same.",
          "type": "object",
          "required": ["step", "atMs", "inviteId", "hostScreenCode", "guestScreenCode", "decision", "guestView"],
          "additionalProperties": false,
          "properties": {
            "note": {"$ref": "#/$defs/stepNote"}, "step": {"const": "comparison"}, "atMs": {"$ref": "#/$defs/atMs"}, "inviteId": {"$ref": "#/$defs/id"},
            "hostScreenCode": {"$ref": "#/$defs/sixDigits"}, "guestScreenCode": {"$ref": "#/$defs/sixDigits"},
            "decision": {"enum": ["allow", "decline"]},
            "guestView": {"oneOf": [{"type": "null"}, {"type": "object", "required": ["hostKeySha256", "guestKeySha256", "exporter"], "additionalProperties": false,
                                                        "properties": {"hostKeySha256": {"$ref": "#/$defs/sha256"}, "guestKeySha256": {"$ref": "#/$defs/sha256"}, "exporter": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/sha256"}]}}}]}
          }
        },
        {
          "type": "object",
          "required": ["step", "atMs", "kind", "newHostEpoch", "newHostDeviceId", "newHostKeySha256"],
          "additionalProperties": false,
          "properties": {
            "note": {"$ref": "#/$defs/stepNote"}, "step": {"const": "restart"}, "atMs": {"$ref": "#/$defs/atMs"},
            "kind": {"enum": ["hostRestart", "hostTransfer"]},
            "newHostEpoch": {"$ref": "#/$defs/posInt"}, "newHostDeviceId": {"$ref": "#/$defs/id"}, "newHostKeySha256": {"$ref": "#/$defs/sha256"}
          }
        },
        {
          "description": "What the host's screen showed at atMs. The reference recomputes every field.",
          "type": "object",
          "required": ["step", "atMs", "display"],
          "additionalProperties": false,
          "properties": {
            "note": {"$ref": "#/$defs/stepNote"}, "step": {"const": "observe"}, "atMs": {"$ref": "#/$defs/atMs"},
            "display": {
              "type": "object", "required": ["recordingOn", "devices"], "additionalProperties": false,
              "properties": {
                "recordingOn": {"oneOf": [{"type": "null"}, {"type": "object", "required": ["n", "m"], "additionalProperties": false, "properties": {"n": {"$ref": "#/$defs/nonNegInt"}, "m": {"$ref": "#/$defs/nonNegInt"}}}]},
                "devices": {"type": "array", "maxItems": 6, "items": {
                  "type": "object",
                  "required": ["deviceId", "slot", "freshness", "contactAgeMs", "state", "label", "ready", "stillAgeMs"],
                  "additionalProperties": false,
                  "properties": {
                    "deviceId": {"$ref": "#/$defs/id"},
                    "slot": {"$ref": "studio-common.schema.json#/$defs/placementSlot"},
                    "freshness": {"enum": ["Local", "Fresh", "Delayed", "Unknown"]},
                    "contactAgeMs": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/nonNegInt"}]},
                    "state": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/captureState"}]},
                    "label": {"oneOf": [{"type": "null"}, {"type": "string", "minLength": 1, "maxLength": 80}]},
                    "ready": {"oneOf": [{"type": "null"}, {"type": "boolean"}]},
                    "stillAgeMs": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/nonNegInt"}]}
                  }
                }}
              }
            }
          }
        }
      ]
    }
  }
}
"""#,
        "source-manifest.schema.json": #"""
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "JOVRA Studio SourceManifest (jovra.source-manifest/1)",
  "description": "What each camera or B-roll file actually is, measured from the file (never inferred from a name): immutable hash, size, duration, codec, dimensions, rotation, colour/HDR, rational timebase, variable-frame-rate flag, audio, lens, capture hints (host time and wall clock are hints, not synchronization), recorded segments and restarts, normalized proxies with their original-PTS tables, and server-side verification. Originals are never replaced by proxies.",
  "type": "object",
  "required": ["schemaVersion", "projectId", "revision", "sample", "createdAt", "sources"],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {"const": "jovra.source-manifest/1"},
    "projectId": {"$ref": "studio-common.schema.json#/$defs/id"},
    "revision": {"$ref": "studio-common.schema.json#/$defs/revision"},
    "sample": {"$ref": "studio-common.schema.json#/$defs/sample"},
    "createdAt": {"$ref": "studio-common.schema.json#/$defs/dateTime"},
    "sources": {"type": "array", "minItems": 1, "maxItems": 18, "items": {"$ref": "#/$defs/source"}}
  },
  "$defs": {
    "source": {
      "type": "object",
      "required": ["sourceId", "role", "slot", "isPrimary", "deviceLabel", "original", "lens", "captureHints", "segments", "proxies", "verification"],
      "additionalProperties": false,
      "properties": {
        "sourceId": {"$ref": "studio-common.schema.json#/$defs/id"},
        "role": {"enum": ["match", "broll"]},
        "slot": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/placementSlot"}]},
        "isPrimary": {"type": "boolean"},
        "deviceLabel": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/userText"}]},
        "original": {
          "type": "object",
          "required": ["sha256", "sizeBytes", "container", "durationUs", "timescale", "startPts", "frameCount", "nominalFps", "vfr", "video", "colour", "audio"],
          "additionalProperties": false,
          "properties": {
            "sha256": {"$ref": "studio-common.schema.json#/$defs/sha256"},
            "sizeBytes": {"type": "integer", "minimum": 1, "maximum": 1000000000000},
            "container": {"enum": ["mov", "mp4", "m4v"]},
            "durationUs": {"$ref": "studio-common.schema.json#/$defs/posInt"},
            "timescale": {"description": "The video track's media timescale (e.g. 600 or 90000); PTS are integers on it.", "$ref": "studio-common.schema.json#/$defs/posInt"},
            "startPts": {"$ref": "studio-common.schema.json#/$defs/rationalTime"},
            "frameCount": {"$ref": "studio-common.schema.json#/$defs/posInt"},
            "nominalFps": {"$ref": "studio-common.schema.json#/$defs/fps"},
            "vfr": {"description": "True when decoded frame durations vary; average fps then proves nothing about a constant clock.", "type": "boolean"},
            "video": {
              "type": "object",
              "required": ["codec", "width", "height", "rotationDegrees", "pixelAspect"],
              "additionalProperties": false,
              "properties": {
                "codec": {"enum": ["h264", "hevc", "prores", "other"]},
                "width": {"type": "integer", "minimum": 2, "maximum": 7680},
                "height": {"type": "integer", "minimum": 2, "maximum": 7680},
                "rotationDegrees": {"enum": [0, 90, 180, 270]},
                "pixelAspect": {"$ref": "studio-common.schema.json#/$defs/rational"}
              }
            },
            "colour": {
              "type": "object",
              "required": ["primaries", "transfer", "matrix", "range", "bitDepth", "hdr"],
              "additionalProperties": false,
              "properties": {
                "primaries": {"enum": ["bt709", "bt2020", "p3", "unknown"]},
                "transfer": {"enum": ["bt709", "srgb", "hlg", "pq", "unknown"]},
                "matrix": {"enum": ["bt709", "bt2020nc", "bt601", "unknown"]},
                "range": {"enum": ["limited", "full"]},
                "bitDepth": {"enum": [8, 10, 12]},
                "hdr": {"type": "boolean"}
              }
            },
            "audio": {
              "oneOf": [
                {"type": "null"},
                {
                  "type": "object",
                  "required": ["codec", "sampleRate", "channels"],
                  "additionalProperties": false,
                  "properties": {
                    "codec": {"enum": ["aac", "pcm", "alac", "other"]},
                    "sampleRate": {"enum": [44100, 48000]},
                    "channels": {"type": "integer", "minimum": 1, "maximum": 8}
                  }
                }
              ]
            }
          }
        },
        "lens": {
          "type": "object",
          "required": ["kind", "zoomFactor"],
          "additionalProperties": false,
          "properties": {
            "kind": {"enum": ["ultra-wide", "wide", "telephoto", "unknown"]},
            "zoomFactor": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/decimalString"}]}
          }
        },
        "captureHints": {
          "description": "Hints only. Pairing, the host's start button, room clock pings and file times never establish frame synchronization.",
          "type": "object",
          "required": ["wallClockStart", "wallClockSource", "roomOffsetUs", "roomRoundTripUs"],
          "additionalProperties": false,
          "properties": {
            "wallClockStart": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/dateTime"}]},
            "wallClockSource": {"enum": ["device", "room-ntp", "file-metadata", "none"]},
            "roomOffsetUs": {"description": "Room clock minus this device's host clock, in microseconds, measured at pairing (null when not paired). A segment's room time is fileZeroHostNs / 1000 + roomOffsetUs; bundle.capture_hints turns that into a from-hints prior.", "type": ["integer", "null"]},
            "roomRoundTripUs": {"type": ["integer", "null"], "minimum": 0}
          }
        },
        "segments": {
          "type": "array",
          "minItems": 1,
          "maxItems": 64,
          "items": {
            "type": "object",
            "required": ["segmentId", "index", "reason", "fileZeroHostNs", "startPts", "durationUs", "frameCount"],
            "additionalProperties": false,
            "properties": {
              "segmentId": {"$ref": "studio-common.schema.json#/$defs/id"},
              "index": {"$ref": "studio-common.schema.json#/$defs/nonNegInt"},
              "reason": {"enum": ["start", "restart", "thermal", "interruption", "import"]},
              "fileZeroHostNs": {"description": "Host-clock time of the segment's file zero (journalled on capture); null for imports.", "type": ["integer", "null"], "minimum": 0},
              "startPts": {"$ref": "studio-common.schema.json#/$defs/rationalTime"},
              "durationUs": {"$ref": "studio-common.schema.json#/$defs/posInt"},
              "frameCount": {"$ref": "studio-common.schema.json#/$defs/posInt"}
            }
          }
        },
        "proxies": {
          "type": "array",
          "maxItems": 4,
          "items": {
            "type": "object",
            "required": ["class", "sha256", "fps", "width", "height", "frameCount", "ptsTableSha256", "normalizerVersion", "rotationApplied", "toneMapped"],
            "additionalProperties": false,
            "properties": {
              "class": {"description": "analysis keeps original timestamps; render is constant-frame-rate, rotation-baked, SDR, zero-start.", "enum": ["analysis", "render"]},
              "sha256": {"$ref": "studio-common.schema.json#/$defs/sha256"},
              "fps": {"$ref": "studio-common.schema.json#/$defs/fps"},
              "width": {"type": "integer", "minimum": 2, "maximum": 7680},
              "height": {"type": "integer", "minimum": 2, "maximum": 7680},
              "frameCount": {"$ref": "studio-common.schema.json#/$defs/posInt"},
              "ptsTableSha256": {"description": "Hash of the original-PTS -> proxy-frame table.", "$ref": "studio-common.schema.json#/$defs/sha256"},
              "normalizerVersion": {"type": "string", "pattern": "^[a-z0-9-]+@[0-9]+\\.[0-9]+\\.[0-9]+$"},
              "rotationApplied": {"type": "boolean"},
              "toneMapped": {"type": "boolean"}
            }
          }
        },
        "verification": {
          "type": "object",
          "required": ["status", "method", "verifiedAt"],
          "additionalProperties": false,
          "properties": {
            "status": {"enum": ["unverified", "verified", "failed"]},
            "method": {"oneOf": [{"type": "null"}, {"enum": ["sha256-full-read-device", "sha256-full-read-server"]}]},
            "verifiedAt": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/dateTime"}]}
          }
        }
      }
    }
  }
}
"""#,
        "storage-provider-capability.schema.json": #"""
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "JOVRA Studio storage-provider capabilities (jovra.storage-providers/1)",
  "description": "Truthful capability states for optional archive/import providers behind one adapter interface. A provider is an archive, never the database or the compute engine (processing is always false). iCloud Drive is reached through the Files picker on iOS only; Google Drive, Box and Dropbox need their own verified integrations before they are active. Credentials are Keychain/EncryptedSharedPreferences references, never tokens.",
  "type": "object",
  "required": ["schemaVersion", "sample", "environment", "providers"],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {"const": "jovra.storage-providers/1"},
    "sample": {"$ref": "studio-common.schema.json#/$defs/sample"},
    "environment": {"$ref": "studio-common.schema.json#/$defs/environment"},
    "providers": {
      "type": "array",
      "minItems": 1,
      "maxItems": 8,
      "items": {
        "type": "object",
        "required": ["provider", "status", "integration", "platforms", "operations", "credentialRef", "folderRef", "processing", "lastVerifiedAt"],
        "additionalProperties": false,
        "properties": {
          "provider": {"enum": ["device", "icloud-drive-files", "google-drive", "box", "dropbox"]},
          "status": {"enum": ["active", "choose-folder", "not-connected", "planned", "unavailable", "token-expired", "disconnected"]},
          "integration": {"enum": ["local", "files-picker", "oauth-verified", "oauth-planned"]},
          "platforms": {
            "type": "object",
            "required": ["ios", "android"],
            "additionalProperties": false,
            "properties": {"ios": {"type": "boolean"}, "android": {"type": "boolean"}}
          },
          "operations": {
            "type": "object",
            "required": ["exportFiles", "importFiles", "archiveSidecar", "resume", "quota"],
            "additionalProperties": false,
            "properties": {
              "exportFiles": {"type": "boolean"},
              "importFiles": {"type": "boolean"},
              "archiveSidecar": {"type": "boolean"},
              "resume": {"type": "boolean"},
              "quota": {"type": "boolean"}
            }
          },
          "credentialRef": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/id"}]},
          "folderRef": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/id"}]},
          "processing": {"const": false},
          "lastVerifiedAt": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/dateTime"}]}
        }
      }
    }
  }
}
"""#,
        "story-brief.schema.json": #"""
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "JOVRA Studio StoryBrief (jovra.story-brief/1)",
  "description": "The planner-facing story proposal (the film-engine research calls its planner output a StoryPlan; this is that contract). A heuristic or model planner fills it with ids and enums only: keepers, B-roll items, notes, cues, stats, catalog templates and treatments. It never carries frame numbers, score digits, metric values, quotes, paths or filter strings. reasonForReview and omitted ideas appear only in the review UI. Deterministic code compiles a valid brief into a jovra.edit-plan/2.",
  "type": "object",
  "required": ["schemaVersion", "briefId", "projectId", "revision", "sample", "profile", "bindings", "planner", "feelingKey", "audience", "durationTargetSeconds", "aspect", "primaryAudioPolicy", "effectIntensity", "cleanAlternate", "privacy", "music", "narration", "beats", "comparisons", "omitted", "unresolved"],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {"const": "jovra.story-brief/1"},
    "briefId": {"$ref": "studio-common.schema.json#/$defs/id"},
    "projectId": {"$ref": "studio-common.schema.json#/$defs/id"},
    "revision": {"$ref": "studio-common.schema.json#/$defs/revision"},
    "sample": {"$ref": "studio-common.schema.json#/$defs/sample"},
    "profile": {
      "type": "object",
      "required": ["id", "revision"],
      "additionalProperties": false,
      "properties": {"id": {"$ref": "studio-common.schema.json#/$defs/profileId"}, "revision": {"$ref": "studio-common.schema.json#/$defs/revision"}}
    },
    "bindings": {
      "type": "object",
      "required": ["eventRevision", "syncRevision", "keeperCatalogRevision", "brollCatalogRevision"],
      "additionalProperties": false,
      "properties": {
        "eventRevision": {"$ref": "studio-common.schema.json#/$defs/revision"},
        "syncRevision": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/revision"}]},
        "keeperCatalogRevision": {"$ref": "studio-common.schema.json#/$defs/revision"},
        "brollCatalogRevision": {"$ref": "studio-common.schema.json#/$defs/revision"}
      }
    },
    "planner": {
      "description": "Which planner proposed this brief. A model id is pinned and server-side only; 'heuristic' is the default and the fallback.",
      "type": "object",
      "required": ["kind", "modelId", "adapterVersion"],
      "additionalProperties": false,
      "properties": {
        "kind": {"enum": ["heuristic", "model", "user"]},
        "modelId": {"oneOf": [{"type": "null"}, {"type": "string", "pattern": "^[a-z0-9][a-z0-9.-]{1,63}$"}]},
        "adapterVersion": {"type": "string", "pattern": "^[a-z0-9-]+@[0-9]+\\.[0-9]+\\.[0-9]+$"}
      }
    },
    "feelingKey": {"$ref": "studio-common.schema.json#/$defs/templateId"},
    "audience": {"enum": ["self", "coach", "family", "private-share"]},
    "durationTargetSeconds": {"type": "integer", "minimum": 10, "maximum": 14400},
    "aspect": {"$ref": "studio-common.schema.json#/$defs/aspect"},
    "primaryAudioPolicy": {"enum": ["continuous-primary-court-audio", "no-audio"]},
    "effectIntensity": {"enum": ["low", "medium"]},
    "cleanAlternate": {"type": "boolean"},
    "privacy": {
      "type": "object",
      "required": ["venueVisible", "faces"],
      "additionalProperties": false,
      "properties": {"venueVisible": {"type": "boolean"}, "faces": {"enum": ["show", "blur-bystanders"]}}
    },
    "music": {"oneOf": [{"type": "null"}, {"type": "object", "required": ["assetId", "rightsRecordId"], "additionalProperties": false, "properties": {"assetId": {"$ref": "studio-common.schema.json#/$defs/id"}, "rightsRecordId": {"$ref": "studio-common.schema.json#/$defs/id"}}}]},
    "narration": {"oneOf": [{"type": "null"}, {"type": "object", "required": ["voice", "consentRecordId"], "additionalProperties": false, "properties": {"voice": {"enum": ["user-recorded", "generated"]}, "consentRecordId": {"$ref": "studio-common.schema.json#/$defs/id"}}}]},
    "beats": {"type": "array", "minItems": 1, "maxItems": 64, "items": {"$ref": "#/$defs/beat"}},
    "comparisons": {"type": "array", "maxItems": 8, "items": {"$ref": "#/$defs/comparison"}},
    "omitted": {
      "type": "array",
      "maxItems": 32,
      "items": {
        "type": "object",
        "required": ["idea", "missingEvidence"],
        "additionalProperties": false,
        "properties": {"idea": {"$ref": "studio-common.schema.json#/$defs/userText"}, "missingEvidence": {"$ref": "studio-common.schema.json#/$defs/userText"}}
      }
    },
    "unresolved": {"type": "array", "maxItems": 16, "items": {"$ref": "studio-common.schema.json#/$defs/userText"}}
  },
  "$defs": {
    "beat": {
      "type": "object",
      "required": ["beatId", "role", "treatment", "keeperId", "brollId", "angle", "replaySpeedDen", "overlays", "noteId", "templateId", "reasonForReview"],
      "additionalProperties": false,
      "properties": {
        "beatId": {"$ref": "studio-common.schema.json#/$defs/id"},
        "role": {"enum": ["goal", "context", "example", "cue", "drill", "checkpoint", "intro", "point", "game-transition", "replay", "final-score", "opening", "build", "key-exchange", "payoff", "close", "early-evidence", "lesson", "recent-evidence", "what-changed", "next-goal", "arrival", "preparation", "match-moment", "highlight", "after", "dedication"]},
        "treatment": {"enum": ["live", "replay", "freeze", "title-card", "broll"]},
        "keeperId": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/id"}]},
        "brollId": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/id"}]},
        "angle": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/placementSlot"}]},
        "replaySpeedDen": {"oneOf": [{"type": "null"}, {"enum": [1, 2, 4, 8]}]},
        "overlays": {
          "type": "array",
          "maxItems": 8,
          "items": {
            "type": "object",
            "required": ["kind", "refId"],
            "additionalProperties": false,
            "properties": {"kind": {"$ref": "studio-common.schema.json#/$defs/overlayKind"}, "refId": {"$ref": "studio-common.schema.json#/$defs/id"}}
          }
        },
        "noteId": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/id"}]},
        "templateId": {"oneOf": [{"type": "null"}, {"$ref": "studio-common.schema.json#/$defs/templateId"}]},
        "reasonForReview": {"$ref": "studio-common.schema.json#/$defs/userText"}
      }
    },
    "side": {
      "type": "object",
      "required": ["date", "sessionIds", "numerator", "denominator", "provenance"],
      "additionalProperties": false,
      "properties": {
        "date": {"$ref": "studio-common.schema.json#/$defs/date"},
        "sessionIds": {"type": "array", "minItems": 1, "maxItems": 16, "items": {"$ref": "studio-common.schema.json#/$defs/id"}},
        "numerator": {"$ref": "studio-common.schema.json#/$defs/nonNegInt"},
        "denominator": {"$ref": "studio-common.schema.json#/$defs/nonNegInt"},
        "provenance": {"$ref": "studio-common.schema.json#/$defs/provenanceStatus"}
      }
    },
    "comparison": {
      "description": "A dated before/after of one stored stat. The display strings are derived (integer pct, percentage points) and re-checked; '% improvement' wording on proportions is never produced.",
      "type": "object",
      "required": ["comparisonId", "statId", "metricDefinitionId", "methodId", "selectionRule", "claim", "before", "after", "display"],
      "additionalProperties": false,
      "properties": {
        "comparisonId": {"$ref": "studio-common.schema.json#/$defs/id"},
        "statId": {"$ref": "studio-common.schema.json#/$defs/id"},
        "metricDefinitionId": {"$ref": "studio-common.schema.json#/$defs/id"},
        "methodId": {"$ref": "studio-common.schema.json#/$defs/id"},
        "selectionRule": {"enum": ["all", "seeded-random", "user-chosen"]},
        "claim": {"enum": ["change", "chronology"]},
        "before": {"$ref": "#/$defs/side"},
        "after": {"$ref": "#/$defs/side"},
        "display": {
          "type": "object",
          "required": ["before", "after", "delta"],
          "additionalProperties": false,
          "properties": {"before": {"type": "string", "maxLength": 40}, "after": {"type": "string", "maxLength": 40}, "delta": {"type": "string", "maxLength": 40}}
        }
      }
    }
  }
}
"""#,
        "story-profile.schema.json": #"""
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "JOVRA Studio story-profile catalog (jovra.story-profile-catalog/1)",
  "description": "The five versioned story profiles. Text fields are carried over unchanged from design-reference/studio/brief/story-profiles.json (jovra.story-profiles/1; validate_studio.py checks they still match). Each profile adds a machine-checkable grammar (film-engine research section 6, proposed defaults to tune on real footage) that the EDL validator enforces. Changing a grammar bumps that profile's revision, which makes plans bound to the old revision stale.",
  "type": "object",
  "required": ["schemaVersion", "derivedFrom", "status", "defaults", "profiles"],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {"const": "jovra.story-profile-catalog/1"},
    "derivedFrom": {"const": "design-reference/studio/brief/story-profiles.json#jovra.story-profiles/1"},
    "status": {"type": "string", "maxLength": 300},
    "defaults": {
      "type": "object",
      "required": ["preserveOriginals", "inventFootage", "inventMetrics", "publishAutomatically", "music", "generatedCommentary", "rallyActionSpeed", "effectIntensity", "sourceAudio", "metricProvenanceVisible"],
      "additionalProperties": false,
      "properties": {
        "preserveOriginals": {"const": true},
        "inventFootage": {"const": false},
        "inventMetrics": {"const": false},
        "publishAutomatically": {"const": false},
        "music": {"const": "none"},
        "generatedCommentary": {"const": "off"},
        "rallyActionSpeed": {"const": 1},
        "effectIntensity": {"const": "low"},
        "sourceAudio": {"const": "continuous primary track"},
        "metricProvenanceVisible": {"const": true}
      }
    },
    "profiles": {"type": "array", "minItems": 5, "maxItems": 5, "items": {"$ref": "#/$defs/profile"}}
  },
  "$defs": {
    "text": {"type": "string", "minLength": 1, "maxLength": 400},
    "provenanceList": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "studio-common.schema.json#/$defs/provenanceStatus"}},
    "msRange": {
      "type": "object",
      "required": ["min", "max"],
      "additionalProperties": false,
      "properties": {"min": {"type": "integer", "minimum": 0}, "max": {"type": "integer", "minimum": 0}}
    },
    "profile": {
      "type": "object",
      "required": ["id", "revision", "name", "intent", "recommendedDurationSeconds", "beats", "editing", "mustNot", "fallback", "exportAudio", "grammar"],
      "additionalProperties": false,
      "properties": {
        "id": {"$ref": "studio-common.schema.json#/$defs/profileId"},
        "revision": {"$ref": "studio-common.schema.json#/$defs/revision"},
        "name": {"$ref": "#/$defs/text"},
        "intent": {"$ref": "#/$defs/text"},
        "recommendedDurationSeconds": {"type": "array", "prefixItems": [{"type": "integer", "minimum": 1}, {"type": "integer", "minimum": 1}], "minItems": 2, "maxItems": 2},
        "beats": {"type": "array", "minItems": 1, "maxItems": 12, "items": {"$ref": "#/$defs/text"}},
        "editing": {
          "type": "object",
          "additionalProperties": {"oneOf": [{"$ref": "#/$defs/text"}, {"type": "array", "items": {"$ref": "#/$defs/text"}}]}
        },
        "mustNot": {"type": "array", "minItems": 1, "maxItems": 12, "items": {"$ref": "#/$defs/text"}},
        "fallback": {"$ref": "#/$defs/text"},
        "exportAudio": {
          "description": "Spec D-1 / SD5: the private in-app film keeps the court audio whatever this says. For every file that leaves the app (Save to Photos or Files, Download, share link, Prepare for YouTube) the Include audio switch starts at includeByDefault and is always shown; a no-audio export is its own verified artifact (audioCodec null). Junior mode overrides this: no audio and no switch. On only for Rally Pulse and Court Memories.",
          "type": "object",
          "required": ["includeByDefault", "switchShown", "juniorMode"],
          "additionalProperties": false,
          "properties": {
            "includeByDefault": {"type": "boolean"},
            "switchShown": {"const": true},
            "juniorMode": {"const": "no-audio-no-switch"}
          }
        },
        "grammar": {
          "type": "object",
          "required": ["durationSeconds", "chronology", "ops", "replaySpeedDens", "transitions", "maxTransitionMs", "freezeMs", "cardMs", "replayMaxMs", "reframe", "gradePresets", "narration", "music", "overlays"],
          "additionalProperties": false,
          "properties": {
            "durationSeconds": {"$ref": "#/$defs/msRange"},
            "chronology": {"enum": ["strict", "free"]},
            "ops": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "studio-common.schema.json#/$defs/segmentOp"}},
            "replaySpeedDens": {"type": "array", "uniqueItems": true, "items": {"enum": [1, 2, 4, 8]}},
            "transitions": {"type": "array", "uniqueItems": true, "items": {"enum": ["dissolve", "dip"]}},
            "maxTransitionMs": {"type": "integer", "minimum": 0, "maximum": 1000},
            "freezeMs": {"$ref": "#/$defs/msRange"},
            "cardMs": {"$ref": "#/$defs/msRange"},
            "replayMaxMs": {"type": "integer", "minimum": 0, "maximum": 8000},
            "reframe": {"enum": ["if-box-fits", "letterbox-only"]},
            "gradePresets": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "studio-common.schema.json#/$defs/gradePreset"}},
            "narration": {"type": "boolean"},
            "music": {"type": "boolean"},
            "overlays": {
              "description": "Overlay kinds this profile uses, each with the provenance it may display.",
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "score": {"$ref": "#/$defs/provenanceList"},
                "metric": {"$ref": "#/$defs/provenanceList"},
                "note": {"$ref": "#/$defs/provenanceList"},
                "cue": {"$ref": "#/$defs/provenanceList"},
                "annotation": {"$ref": "#/$defs/provenanceList"}
              }
            }
          }
        }
      }
    }
  }
}
"""#,
        "studio-common.schema.json": #"""
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "JOVRA Studio shared definitions",
  "description": "Definitions shared by every JOVRA Studio record. Not a document type. No $id: references resolve relative to this folder. provenanceStatus mirrors spec/schemas/common.schema.json exactly; scripts/spec/validate_studio.py fails if they drift.",
  "$defs": {
    "id": {
      "description": "Opaque identifier. Letters, digits, '_' and '-' only, so an id can never be a path, URL or command.",
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$"
    },
    "templateId": {
      "description": "A catalog template or preset id (card.goal, label.replay, warm-court-1). Never free text.",
      "type": "string",
      "pattern": "^[a-z][a-z0-9-]{0,31}(\\.[a-z0-9][a-z0-9-]{0,31}){0,3}$"
    },
    "sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "revision": {"description": "Monotonic document revision. A newer revision makes plans and films bound to an older one stale.", "type": "integer", "minimum": 1},
    "dateTime": {
      "description": "RFC 3339 timestamp in UTC with a Z suffix.",
      "type": "string",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,3})?Z$"
    },
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "decimalString": {"type": "string", "pattern": "^-?[0-9]+(\\.[0-9]+)?$"},
    "nonNegInt": {"type": "integer", "minimum": 0},
    "posInt": {"type": "integer", "minimum": 1},
    "sample": {"description": "True for fictional demo data, which every surface badges 'Sample'.", "type": "boolean"},
    "environment": {"description": "Local demo (no network, tokens, uploads or charges), isolated test backend, or live backend.", "enum": ["demo", "test", "live"]},
    "rational": {
      "type": "object",
      "required": ["num", "den"],
      "additionalProperties": false,
      "properties": {"num": {"type": "integer", "minimum": 0}, "den": {"type": "integer", "minimum": 1}}
    },
    "fps": {
      "description": "Exact frame rate num/den, e.g. 30/1 or 30000/1001.",
      "type": "object",
      "required": ["num", "den"],
      "additionalProperties": false,
      "properties": {"num": {"type": "integer", "minimum": 1, "maximum": 240000}, "den": {"type": "integer", "minimum": 1, "maximum": 1001}}
    },
    "rate": {
      "description": "Clock rate as an exact rational (session seconds per source second). den is 1000000000, so the rate is held to 1 part per billion.",
      "type": "object",
      "required": ["num", "den"],
      "additionalProperties": false,
      "properties": {"num": {"type": "integer", "minimum": 900000000, "maximum": 1100000000}, "den": {"const": 1000000000}}
    },
    "rationalTime": {
      "description": "A time on a media clock: value / timescale seconds. Used for original PTS so variable-frame-rate originals can be rebuilt.",
      "type": "object",
      "required": ["value", "timescale"],
      "additionalProperties": false,
      "properties": {"value": {"type": "integer", "minimum": 0}, "timescale": {"type": "integer", "minimum": 1}}
    },
    "intervalUs": {
      "description": "Half-open interval [startUs, endUs) in integer microseconds.",
      "type": "object",
      "required": ["startUs", "endUs"],
      "additionalProperties": false,
      "properties": {"startUs": {"type": "integer", "minimum": 0}, "endUs": {"type": "integer", "minimum": 0}}
    },
    "frameWindow": {
      "description": "Half-open window [inFrame, outFrame) of render-proxy frames.",
      "type": "object",
      "required": ["inFrame", "outFrame"],
      "additionalProperties": false,
      "properties": {"inFrame": {"type": "integer", "minimum": 0}, "outFrame": {"type": "integer", "minimum": 1}}
    },
    "positionMm": {
      "description": "Court coordinates in integer millimetres: x across the court (0 on the centre line), y along it (0 at the net, negative towards the near/primary end), z height above the court surface.",
      "type": "object",
      "required": ["xMm", "yMm", "zMm"],
      "additionalProperties": false,
      "properties": {
        "xMm": {"type": "integer", "minimum": -60000, "maximum": 60000},
        "yMm": {"type": "integer", "minimum": -60000, "maximum": 60000},
        "zMm": {"type": "integer", "minimum": 0, "maximum": 20000}
      }
    },
    "placementSlot": {
      "description": "Build-your-match placements (screen 22): 1 near baseline (primary), 2 far baseline, 3-6 corners; custom for an imported or freely placed angle.",
      "enum": ["near-baseline", "far-baseline", "near-left-corner", "near-right-corner", "far-left-corner", "far-right-corner", "custom"]
    },
    "provenanceStatus": {
      "description": "How a value was produced (ADR-0004). Must equal spec/schemas/common.schema.json#/$defs/provenanceStatus.",
      "enum": ["manual", "estimated", "reviewed", "validated"]
    },
    "producer": {
      "description": "Who produced a value: the user, a coach, a capability model, a deterministic rule, an import or the sample generator.",
      "type": "string",
      "pattern": "^(user|coach|model:[A-Za-z0-9._-]+@[A-Za-z0-9._+-]+|rule:[A-Za-z0-9._-]+@[A-Za-z0-9._+-]+|import:[A-Za-z0-9._-]+|sample:[A-Za-z0-9._-]+@[A-Za-z0-9._+-]+)$"
    },
    "capabilityId": {"type": "string", "pattern": "^[a-z][a-zA-Z0-9]*(\\.[a-z][a-zA-Z0-9]*)*$"},
    "profileId": {"enum": ["coach-cut", "match-broadcast", "rally-pulse", "progress-story", "court-memories"]},
    "aspect": {"enum": ["16:9", "9:16", "1:1", "4:5"]},
    "segmentOp": {"description": "EDL v2 video operations.", "enum": ["live", "broll", "replay", "freeze", "title-card"]},
    "transitionType": {"enum": ["cut", "dissolve", "dip"]},
    "audioRoute": {"description": "Bed routes in EDL v2. music and narration are separate optional lanes.", "enum": ["primary-bed", "alt-bed", "hold-bed", "silence"]},
    "overlayKind": {"enum": ["score", "metric", "note", "cue", "annotation"]},
    "gradePreset": {"enum": ["none", "warm-court-1"]},
    "speed": {
      "description": "Allowed playback speeds: 1 for live and B-roll; 1/2, 1/4, 1/8 for labelled replays.",
      "type": "object",
      "required": ["num", "den"],
      "additionalProperties": false,
      "properties": {"num": {"const": 1}, "den": {"enum": [1, 2, 4, 8]}}
    },
    "credits": {"description": "Studio Credits, the unit of quote, cap, reservation and receipt. Integer only.", "type": "integer", "minimum": 0, "maximum": 1000},
    "userText": {"description": "Text a person typed. Rendered as text, never interpreted.", "type": "string", "minLength": 1, "maxLength": 500}
  }
}
"""#,
        "studio-media-demo-subset.schema.json": #"""
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "JOVRA Studio bundled demo subset (jovra.studio-media-demo-subset/1)",
  "description": "Which generated Studio fixture media the app bundles for its demo (S08), where the installer puts it and the size budget it must fit. Written by scripts/media/studio/render_studio.py and read by scripts/media/studio/install_demo.py. Every file is synthetic and labelled Sample.",
  "type": "object",
  "required": ["schemaVersion", "sample", "installTo", "budgetBytes", "installer", "files"],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {"const": "jovra.studio-media-demo-subset/1"},
    "sample": {"const": true},
    "installTo": {"const": "ios/Jovra/Resources/StudioSampleMedia"},
    "budgetBytes": {"type": "integer", "minimum": 1, "maximum": 25000000},
    "installer": {"const": "scripts/media/studio/install_demo.py"},
    "files": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["manifest", "fileName", "role"],
        "additionalProperties": false,
        "properties": {
          "manifest": {"type": "string", "pattern": "^media/[A-Za-z]+/[a-z0-9-]+\\.json$"},
          "fileName": {"type": "string", "pattern": "^[a-z0-9-]+\\.mp4$"},
          "role": {"enum": ["barcodeSource", "match", "broll", "angle"]},
          "angle": {"type": "string"}
        }
      }
    }
  }
}
"""#,
        "studio-media-truth.schema.json": #"""
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "JOVRA Studio media fixture ground truth (jovra.studio-media-truth/1)",
  "description": "The committed ground truth of one generated Studio fixture media file (S08). The media itself is never committed: scripts/media/studio/render_studio.py renders it into the git-ignored cache at media.path. Everything except `hashes` is the generator's plan and is recomputed by the Studio validator; `hashes` is what a render proves and every machine reproduces (drawn frames, the jovra.cellLuma.v1 decoded-frame signature, the click-track PCM). The media file's own SHA-256 is machine-specific (encoder builds differ) and is never committed. All content is synthetic and labelled Sample.",
  "type": "object",
  "required": ["schemaVersion", "id", "set", "role", "description", "sample", "band", "generator", "media", "video", "audio", "barcode", "clicks", "labels", "hashes"],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {"const": "jovra.studio-media-truth/1"},
    "id": {"type": "string", "pattern": "^[A-Za-z]+/[a-z0-9-]+$"},
    "set": {"enum": ["barcodeSources", "match", "broll", "angles"]},
    "role": {"enum": ["barcodeSource", "match", "broll", "angle"]},
    "description": {"type": "string", "minLength": 1, "maxLength": 300},
